import{_ as e,c as l,o as i,ah as r}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"山天大畜","description":"周易折中 - 山天大畜","frontmatter":{"title":"山天大畜","description":"周易折中 - 山天大畜"},"headers":[],"relativePath":"classics/zhezhong/032.md","filePath":"classics/zhezhong/032.md"}'),h={name:"classics/zhezhong/032.md"};function n(p,a,d,t,s,o){return i(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="山天大畜" tabindex="-1">山天大畜 <a class="header-anchor" href="#山天大畜" aria-label="Permalink to “山天大畜”">​</a></h1><h3 id="程傳" tabindex="-1">程傳 <a class="header-anchor" href="#程傳" aria-label="Permalink to “程傳”">​</a></h3><p>大畜序卦：有無妄然後可畜，故受之以大畜。無妄則為有實，故可畜聚。大畜所以次無妄也。為卦，艮上乾下，天而在於山中，所畜至大之象。畜為畜止，又為畜聚，止則聚矣。取天在山中之象，則為蘊畜；取艮之止，乾則為畜止，止而後有積，故止為畜義。</p><p>大畜：利貞，不家食，吉，利涉大川。</p><h3 id="本義" tabindex="-1">本義 <a class="header-anchor" href="#本義" aria-label="Permalink to “本義”">​</a></h3><p>大陽也以艮畜乾，又畜之大者也。又以內乾剛健，外艮篤實輝光，是以能日新其德而為畜之大也。以卦變言，此卦自需而來，九自五而上。以卦體言，六五尊而尚之。以卦德言，又能止健，皆非大正不能，故其佔為“利貞不家食吉”也。又六五下應於乾，為應乎天，故其佔又為“利涉大川”也。不家食，謂食祿於朝，不食於家也。</p><h3 id="程傳-1" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-1" aria-label="Permalink to “程傳”">​</a></h3><p>莫大於天，而在山中，艮在上而止乾於下，皆蘊畜至大之象也。在人為學術道德充積於內，乃所畜之大也。凡所畜聚，皆是專言其大者。人之蘊畜，宜得正道，故云“利貞”。若夫異端偏學，所聚至多而不正者，固有矣。既道德充積於內，宜在上位以享天祿，施為於天下，則不獨於一身之吉，天下之吉也。若窮處而自食於家，道之否也，故“不家食吉”。所畜既大，宜施之於時，濟天下之艱險，乃大畜之用也，故“利涉大川”。此只據大畜之義而言，《彖》更以卦之才德而言。諸爻則惟有止畜之義，蓋《易》體道隨宜取明且近者。</p><h3 id="集說" tabindex="-1">集說 <a class="header-anchor" href="#集說" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>朱子語類雲 ：某作《本義》，欲將文王卦辭只大綱依文王本義略說，至其所以然之故，卻於孔子《彖傳》中發之。且如“大畜，利貞，不家食，吉，利涉大川”，只是佔得大畜者為“利貞不家食而吉”，利於涉大川。至於“剛上尚賢”等處，乃孔子發明，各有所主。爻象亦然。如此，則不失文王本意，又可見孔子之意。但今未暇整頓耳。</p></li><li><p>胡氏炳文曰 ：“不家食”是賢者不畜於家而畜於朝，“涉大川”又似有畜極而通之意。要之，兩“利”字，一“吉”字，佔辭自分為三，不必泥而一之也。</p></li></ul><p>象曰：天在山中，大畜；君子以多識前言往行，以畜其德</p><h3 id="本義-1" tabindex="-1">本義 <a class="header-anchor" href="#本義-1" aria-label="Permalink to “本義”">​</a></h3><p>天在山中，不必實有是事，但以其象言之耳。</p><h3 id="程傳-2" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-2" aria-label="Permalink to “程傳”">​</a></h3><p>天為至大，而在山之中，所畜至大之象。君子觀象以大其蘊畜，人之蘊畜由學而大，在多聞前古聖賢之言與行，考跡以觀其用，察言以求其心，識而得之以畜成其德，乃大畜之義也。</p><h3 id="集說-1" tabindex="-1">集說 <a class="header-anchor" href="#集說-1" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>楊氏時曰 ：君子多識前言往行，非徒資聞見而已，所以畜德也。畜德則所畜大矣。世之學者誇多鬥靡，以資見聞而已，亦烏用學為哉？</p></li><li><p>丘氏富國曰 ：大畜言畜德，小畜言懿文。德畜雖同，而文德則德之小者也。</p></li><li><p>張氏清子曰 ：天在山中，畜其氣也。凡山中有雷雨雲風之氣，皆天也。</p></li></ul><p>彖曰：大畜，剛健篤實，輝光日新其德</p><h3 id="本義-2" tabindex="-1">本義 <a class="header-anchor" href="#本義-2" aria-label="Permalink to “本義”">​</a></h3><p>以卦德釋卦名義。</p><h3 id="程傳-3" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-3" aria-label="Permalink to “程傳”">​</a></h3><p>以卦之才德而言也。幹體剛健，艮體篤實。人之才，剛健篤實，則所畜能大，充實而有輝光。畜之不已，則其德日新也。</p><h3 id="集說-2" tabindex="-1">集說 <a class="header-anchor" href="#集說-2" aria-label="Permalink to “集說”">​</a></h3><ul><li>鄭氏汝諧曰：畜有三義：以蘊畜言之，畜德也；以畜養言之，畜賢也；以畜止言之，畜健也。剛健篤實，輝光日新其德，此蘊畜之大者；養賢以及萬民，此畜養之大者；幹天下之至健而四五能畜之，此畜止之大者。故彖傳兼此三者言之。</li></ul><p>剛上而尚賢，能止健，大正也</p><h3 id="本義-3" tabindex="-1">本義 <a class="header-anchor" href="#本義-3" aria-label="Permalink to “本義”">​</a></h3><p>以卦變、卦體釋卦辭。</p><h3 id="程傳-4" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-4" aria-label="Permalink to “程傳”">​</a></h3><p>剛上，陽居上也。陽剛居尊位之上，為尚賢之義；止居健上，為能止健之義。止乎健者，非大正，則安能以剛陽在上與尊尚賢德、能止至健，皆大正之道也。</p><h3 id="集說-3" tabindex="-1">集說 <a class="header-anchor" href="#集說-3" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>郭氏忠孝曰：大有，有賢之卦也；大畜，畜賢之卦也。故曰“剛上而尚賢”。</p></li><li><p>朱子語類雲：能止健，不說健而止，見得是艮來止這幹。</p></li></ul><p>不家食吉，養賢也</p><h3 id="本義-4" tabindex="-1">本義 <a class="header-anchor" href="#本義-4" aria-label="Permalink to “本義”">​</a></h3><p>亦取尚賢之象。</p><h3 id="集說-4" tabindex="-1">集說 <a class="header-anchor" href="#集說-4" aria-label="Permalink to “集說”">​</a></h3><ul><li>梁氏寅曰：養賢者，亦取尚賢之象。自剛上而言，則謂之尚賢，所以盡其禮也；自不家食而言，則謂之養賢，所以重其祿也。</li></ul><p>利涉大川，應乎天也</p><h3 id="本義-5" tabindex="-1">本義 <a class="header-anchor" href="#本義-5" aria-label="Permalink to “本義”">​</a></h3><p>亦以卦體而言。</p><h3 id="程傳-5" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-5" aria-label="Permalink to “程傳”">​</a></h3><p>大畜之人，所宜施其所畜以濟天下，故不食於家則吉。謂居天位，享天祿也。國家養賢，賢者得行其道也。利涉大川，謂大有蘊畜之人，宜濟天下之艱險也。彖更發明卦才，雲所以能涉大川者，以應乎天也。六五君也，下應幹之中爻，乃大畜之君，應幹而行也。所行能應乎天，無艱險之不可濟，況其他乎？</p><h3 id="集說-5" tabindex="-1">集說 <a class="header-anchor" href="#集說-5" aria-label="Permalink to “集說”">​</a></h3><ul><li>胡氏炳文曰：卦有幹體者多曰“利涉大川”，健故也。</li></ul><h3 id="案" tabindex="-1">案 <a class="header-anchor" href="#案" aria-label="Permalink to “案”">​</a></h3><p>尚賢、止健之義，六爻中皆可見。然夫子釋卦，必以“剛健篤實”一句居首者，蓋莫大於天德。剛健者，天德也。人慾畜其天德，非篤實則不能。篤實者，《論語》所謂“重”、《大學》所謂“靜”、《中庸》所謂“暗”。雖至於達天德，而必有以固其聰明聖智。故篤實者，學之所以成始成終。如艮為萬物之所成終，而所成始也。此義最大，故首發之。</p><p>初九：有厲利已</p><h3 id="本義-6" tabindex="-1">本義 <a class="header-anchor" href="#本義-6" aria-label="Permalink to “本義”">​</a></h3><p>乾之三陽為艮所止，故內外之卦各取其義。初九為六四所止，故其佔往則有危而利於止也。</p><h3 id="程傳-6" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-6" aria-label="Permalink to “程傳”">​</a></h3><p>大畜，艮止畜乾也，故乾三爻皆取被止為義，艮三爻皆取止之為義。初以陽剛又健體而居下，必上進者也。六四在上，畜止於已，安能敵在上得位之尊？若犯之而進，則有危厲，故利在已而不進也。在他卦，則四與初為正應相援者也；在大畜，則相應乃為相止畜。上與三皆陽，則為合志，蓋陽皆上進之物，故有同志之象而無相止之義。</p><h3 id="集說-6" tabindex="-1">集說 <a class="header-anchor" href="#集說-6" aria-label="Permalink to “集說”">​</a></h3><ul><li>蔡氏清曰 ：初九不可進而未必能自不進，故戒之雲進則有厲，惟利於已也。若九二之處中能自止而不進者也，則以其所能言之曰“輿說輹”。</li></ul><p>象曰：有厲，利己不犯災也</p><h3 id="程傳-7" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-7" aria-label="Permalink to “程傳”">​</a></h3><p>有危則宜己不可犯災，危而行也，不度其勢而進，有災必矣。</p><p>九二：輿說輹</p><ul><li>蔡氏清曰 ：初九不可進而未必能自不進，故戒之雲進則有厲，惟利於已也。若九二之處中能自止而不進者也，則以其所能言之曰“輿說輹”。</li></ul><h3 id="本義-7" tabindex="-1">本義 <a class="header-anchor" href="#本義-7" aria-label="Permalink to “本義”">​</a></h3><p>九二亦為六五所畜，以其處中故能自止而不進，有此象也。</p><h3 id="程傳-8" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-8" aria-label="Permalink to “程傳”">​</a></h3><p>二為六五所畜止，不可進也。五據在上之尊，豈可犯也？二雖剛健之體，然其處得中道，故進止無失。雖志於進，度其尊之不可，則止而不行，如車輿說去輪輹，謂不行也。</p><p>象曰：輿說輹，中無尤也</p><h3 id="程傳-9" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-9" aria-label="Permalink to “程傳”">​</a></h3><p>輿說輹而不行者，蓋其處得中道，動不失宜，故無過尤也。善莫善於剛中柔中者，不至於過柔耳。剛中中而才也。初九處不得中，故戒以有危宜已；二得中，進止自無過差，故但言輿說輹，謂其能不行也。不行則無尤矣。初與二幹體剛健而不足以進，四與五陰柔而能止。時之盛衰，勢之強弱，學易者所宜深識也。</p><h3 id="集說-7" tabindex="-1">集說 <a class="header-anchor" href="#集說-7" aria-label="Permalink to “集說”">​</a></h3><ul><li>呂氏祖謙曰 ：二以剛而居中，能度其宜，見其不可，自說其輿輹而不行也，故曰中無尤。</li></ul><p>九三：良馬逐，利艱貞，曰閒輿衛，利有攸往</p><h3 id="本義-8" tabindex="-1">本義 <a class="header-anchor" href="#本義-8" aria-label="Permalink to “本義”">​</a></h3><p>三以陽居健極，上以陽居畜極，極而通之時也。又皆陽爻，故不相畜而俱進，有良馬逐之象焉。然過剛銳進，故其佔必戒以艱貞，閒習乃利於有往也。曰“當為日月之日”。</p><h3 id="程傳-10" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-10" aria-label="Permalink to “程傳”">​</a></h3><p>三剛健之極，而上九之陽亦上進之物，又處畜之極而思變也，與三乃不相畜而志同相應以進者也。三以剛健之才而在上者，與合志而進，其進如良馬之馳逐，言其速也。雖其進之勢速，不可恃其才之健與上之應而忘備與慎也，故宜艱難其事而由貞正之道。輿者，用行之物；衛者，所以自防。當自日常閒習其車輿與其防衛，則利有攸往矣。三乾體而居正，能貞者也。當其銳進，故戒以知難與不失其貞也。志既銳於進，雖剛明有時而失，不得不戒也。</p><h3 id="集說-8" tabindex="-1">集說 <a class="header-anchor" href="#集說-8" aria-label="Permalink to “集說”">​</a></h3><ul><li>項氏安世曰 ：初九在初，故稱童牛；九二以剛居柔無𫝑，故為豶豕；九三純乾，故為良馬。</li></ul><p>象曰：利有攸往，上合志也</p><h3 id="程傳-11" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-11" aria-label="Permalink to “程傳”">​</a></h3><p>所以利有攸往者，以與在上者合志也。上九陽性上進，且畜已極，故不下畜三，而與合志上進也。</p><h3 id="集說-9" tabindex="-1">集說 <a class="header-anchor" href="#集說-9" aria-label="Permalink to “集說”">​</a></h3><ul><li>趙氏汝梅曰 ：他卦陰陽應為得，此則為畜；他卦陰陽敵為不胥，與此則為合。</li></ul><p>六四：童牛之牿，元吉</p><h3 id="本義-9" tabindex="-1">本義 <a class="header-anchor" href="#本義-9" aria-label="Permalink to “本義”">​</a></h3><p>童者，未角之稱；牿，施橫木於牛角以防其觸。詩所謂楅衡者也。止之於未角之時，為力則易，大善之吉也，故其象佔如此。學記曰：“禁於未發之謂豫”，正此意也。</p><h3 id="程傳-12" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-12" aria-label="Permalink to “程傳”">​</a></h3><p>以位而言，則四下應於初，畜初者也。初居最下，陽之微者，微而畜之，則易制，猶童牛而加牿，大善而吉也。概論畜道，則四艮體居上位，而得正是以正德居大臣之位，當畜之任者也。大臣之任，上畜止人君之邪心，下畜止天下之惡。人人之惡止於初，則易；既盛而後禁，則扞格而難勝。故上之惡既甚，則雖聖人救之，不能免違拂；下之惡既甚，則雖聖人治之，不能免刑戮。莫若止之於初，如童牛而加牿，則元吉也。牛之性牴觸以角，故牿以制之。若童犢始角而加之以牿，使牴觸之性不發，則易而無傷。以況六四能畜止上下之惡於未發之前，則大善之吉也。</p><h3 id="集說-10" tabindex="-1">集說 <a class="header-anchor" href="#集說-10" aria-label="Permalink to “集說”">​</a></h3><ul><li>朱子語類雲 ：大畜下卦取其能自畜而不進，上卦取其能畜彼而不使進。然四能止之於初，故為力易；五則陽已進而止之，則難以柔居尊，得其機會可制，故亦吉，但不能如四之元吉耳。</li></ul><p>象曰：六四元吉，有喜也</p><h3 id="程傳-13" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-13" aria-label="Permalink to “程傳”">​</a></h3><p>天下之惡已盛而止之，則上勞于禁制，而下傷於刑誅。故畜止於㣲小之前，則大善而吉，不勞而無傷，故可喜也。四之畜初是也，上畜亦然。</p><p>六五：豶豕之牙，吉</p><h3 id="本義-10" tabindex="-1">本義 <a class="header-anchor" href="#本義-10" aria-label="Permalink to “本義”">​</a></h3><p>陽已進而止之，不若初之易矣。然以柔居中而當尊位，是以得其機會而可制，故其象如此。佔雖吉而不言元也。</p><h3 id="程傳-14" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-14" aria-label="Permalink to “程傳”">​</a></h3><p>六五居君位，止畜天下之邪惡。夫以億兆之眾，發其邪欲之心，人君欲力以制之，雖密法嚴刑不能勝也。夫物有總攝，事有機會。聖人操得其要，則視億兆之心猶一心，道之斯行，止之則戢，故不勞而治。其用若豶豕之牙也。豕剛躁之物，而牙為猛利，若強制其牙，則用力勞而不能止其躁猛。雖縶之維之，不能使之變也。若豶去其𫝑，則牙雖存而剛躁自止。其用如此，所以吉也。君子法豶豕之義，知天下之惡不可以力制也，則察其機，持其要，塞絕其本原，故不假刑法嚴峻而惡自止也。且如止盜，民有欲心，見利則動。苟不知教而迫於飢寒，雖刑殺日施，其能勝億兆利慾之心乎？聖人則知所以止之之道，不尚威刑而修政教，使之有農桑之業，知廉恥之道，雖賞之不竊矣。故止惡之道，在知其本，得其要而已。不嚴刑于彼而修政於此，是猶患豕牙之利，不制其牙而豶其𫝑也。</p><p>象曰：六五之吉，有慶也</p><h3 id="程傳-15" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-15" aria-label="Permalink to “程傳”">​</a></h3><p>在上者不知止惡之方，嚴刑以敵民欲，則其傷甚而無功。若知其本，制之有道，則不勞無傷而俗革，天下之福慶也。</p><h3 id="集說-11" tabindex="-1">集說 <a class="header-anchor" href="#集說-11" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>呂氏大臨曰 ：六四六五皆以柔畜剛止健者也。牛之剛健在角，豕之剛健在牙。初九居健之始，其健未著，若童牛然。禁於未發，以牿閒之。及其長也，無所用其健，豈特不暴而已，安於馴柔，可駕而服，故有喜也。九二居健之中，其健已具，若豕之牙漸不可制。六五居尊守中，能以柔道殺其剛暴之氣，若豶豕然。其牙雖剛，莫之能暴，可以養畜而無虞，故有慶也。</p></li><li><p>項氏安世曰 ：喜者據己言之，慶則其喜及人。五居君位，故及人也。若論止物之道，則制之於初乃為大善，故四為元吉，五獨得吉而已。</p></li><li><p>蔡氏清曰 ：五不如四所處之易者，時不同也；四不如五所濟之廣者，位不同也。</p></li></ul><p>上九：何天之衢，亨</p><h3 id="本義-11" tabindex="-1">本義 <a class="header-anchor" href="#本義-11" aria-label="Permalink to “本義”">​</a></h3><p>何天之衢，言何其通達之甚也。畜極而通，豁達無礙，故其象佔如此。</p><h3 id="程傳-16" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-16" aria-label="Permalink to “程傳”">​</a></h3><p>予聞之胡先生曰：“天之衢亨，誤加‘何’字。”事極則反，理之常也。故畜極而亨，小畜畜之小，故極而成大畜，畜之大故極而散。極既當變，又陽性上行，故遂散也。天衢，天路也，謂空虛之中雲氣飛鳥往來，故謂之天衢。天衢之亨，謂其亨通曠闊無有蔽阻也。在畜道則變矣，變而亨，非畜道之亨也。</p><h3 id="集說-12" tabindex="-1">集說 <a class="header-anchor" href="#集說-12" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>張氏浚曰 ：剛在上為何？何謂勝其任？</p></li><li><p>王氏宗傳曰 ：《彖傳》曰“剛上而尚賢”，則上九是也。以陽德而居五之上，為五所尚，此所以有何天之衢之象。天衢，通顯之地也。下之三陽由已上進，故九三曰“良馬逐”，又曰“上合志也”。此賢者之道所以亨也。何如？何校之何？釋文曰：“梁武帝讀音賀是也。”言以身任天下之責，當畜賢之時，為五所尚，主張賢路，賢者之得志莫盛於斯也。</p></li><li><p>呉氏澄曰 ：後漢王延壽《魯靈光殿賦》雲：“荷天衢以元亨。”何作荷，何天之衢其辭，猶詩言“何天之休”，“何天之龍”。大畜者，一陽止於外而三陽藏畜於內，畜極則散，止極則行，故上九雖艮體，至畜之終則不止而行也。</p></li><li><p>胡氏炳文曰 ：隨畜隨發，不足為大畜。惟畜之極而通豁逹無礙，如天衢然。此不徒為仕者之佔，大學章句所謂“用力之久，一旦豁然貫通”者，亦是此意。多識前言往行以畜其德者，以之可也。</p></li><li><p>蔡氏清曰 ：觀畜極而通之意，則知君子患屈之未至耳，不患其不伸也。</p></li></ul><h3 id="案-1" tabindex="-1">案 <a class="header-anchor" href="#案-1" aria-label="Permalink to “案”">​</a></h3><p>何字，程傳以為誤加，本義以為發語，而諸家皆以荷字為解，義亦可從。蓋剛上尚賢者，惟上九一爻當之，且為艮主，是卦之主也，故取尚賢之義，則是賢路大通。卦所謂“不家食”者，此已取艮主之義，則能應天止健；卦所謂“涉大川”者，此故天衢者喻其通也。荷天之衢者，言其遇時之通也。《雜卦》雲：“大畜時也。”正謂此也。呉氏引商頌之詩者，語意尢近。</p><p>象曰：何天之衢，道大行也</p><h3 id="程傳-17" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-17" aria-label="Permalink to “程傳”">​</a></h3><p>何以謂之天衢？以其無止礙，道路大通行也。以天衢非常語，故象特設問曰“何謂天之衢”。以道路大通行取空豁之狀也。以象有“何”字，故爻下亦誤加之。</p><h3 id="集說-13" tabindex="-1">集說 <a class="header-anchor" href="#集說-13" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>㳺氏酢曰 ：畜道之成，賢路自我而四達矣，故曰“何天之衢”。亨。彖曰“剛上而尚賢”，則大畜之義主於上九也。崇俊良以列庶位，推轂賢路，使天下無家食之賢者，上九之任也。天下至於無家食之賢，則道之大行，孰盛於此？</p></li><li><p>沈氏該曰 ：何天之衢，尚賢也。大畜之時，已獨居上五，以柔尚之。畜盛德而處上，止眾賢而聚王庭，以天衢之亨為己之任。畜道至此，賢路不塞，其道盛矣，故曰“道大行也”。</p></li><li><p>呂氏祖謙曰 ：畜極則散，如伊尹樂堯舜之道，居畎畝之中，其畜可謂大矣。必佐湯以發其所蘊，是得時如天之衢也。故曰“道行得時”，行道之謂也。</p></li><li><p>何氏楷曰 ：備於身之謂德，達於世之謂道。道可大行，其亨可知。彖所謂“不家食吉，而利渉大川”者，此也。</p></li></ul><p>總論</p><ul><li><p>胡氏炳文曰：他卦取陰陽相應，此取相畜。內卦受畜以自止為義，外卦能畜以止之為義。獨三與上居內外卦之極，畜極而通，不取止義。</p></li><li><p>葉氏良佩曰：卦彖兼取畜止、畜聚二義，大象專取畜聚義，六爻專取畜止義。初九進則有厲，惟利於己，知難而止者也；九二處得中道，能說輹而不行，時止而止者也；九三與上合志，其進也如良馬之馳逐，此畜極而通之象，然猶以艱貞閒習為戒者，慮其可進而銳於進也；六四當大畜之任，能止惡於初，若童牛始角而加之以牿，則大善之吉也；六五制惡有道，得其機會，故其象為豶豕之牙，其佔雖吉，然比之於四則有間矣；或問六四元吉傳曰有喜，六五之吉乃曰有慶，何也？曰論為力之難易，則四為易，故曰元吉；論其功之廣狹，則五為廣，故曰有慶。上九之“亨”，畜極而大通也，故以天之衢為象，“雲行雨施，天下平也”，其斯以為道大行乎？案 “有厲”“說輹”，則猶“家食”者也，阻於“大川”者也。“牿牛”“豶豕”，則猶治不肖者也，弘濟艱難者也。至“良馬逐”則漸通矣。然猶防賢路之崎嶇，而“日閒輿衛”，故至於“何天之衢”，然後大道夷而險阻去也，卦爻義之相關者在此。</p></li></ul>',114)])])}const m=e(h,[["render",n]]);export{b as __pageData,m as default};
